KEEP = {'Parure Satin & Dentelle Bordeaux':0,'Parure Porte-jarretelles Dentelle Noire':0,'Ensemble Brodé Lavande':0,'Ensemble Filet Brodé':1,'Ensemble Fleurs Brodées':0,
 'Soutien-gorge Pure Dentelle':0,'Soutien-gorge Minimiseur Dentelle':0,'Body Dentelle Été':3,'Body Dos Nu Empiècements':3,'Nuisette Satin Émeraude':2,'Culotte Dentelle Florale':1,
 'Pyjashort Satin & Dentelle':1,'Pyjashort Satiné':2,'Ensemble Sans Couture Brodé':4,'Body Dentelle Festonnée':0,'Body Dentelle Vintage':4,'Kimono Satin Fleurs':0}
def _first(t, k):
    ims = t[8].split(); ims = [ims[k]] + [x for j, x in enumerate(ims) if j != k]
    return t[:8] + (' '.join(ims),)
P = NEW[:1] + [_first(t, KEEP[t[3]]) for t in P if t[3] in KEEP and t[1] == 'Porte-jarretelles'] + NEW[1:] + [_first(t, KEEP[t[3]]) for t in P if t[3] in KEEP and t[1] != 'Porte-jarretelles']
RENAME = {'Bralettes': 'Soutiens-gorge'}
P = [(t[0], RENAME.get(t[1], t[1])) + t[2:] for t in P]

out, seen = [], set()
for pid, cat, cost, name, colors, sizes, desc, details, imgs in P:
    slug = slugify(name)
    while slug in seen: slug += '-2'
    seen.add(slug)
    images = [CDN + (k if '.' in k else k + '.jpg') for k in imgs.split()]
    out.append(dict(slug=slug, name=name, cat=cat, cost=round(cost, 2), images=images, colors=colors, sizes=sizes,
                    desc=desc, details=details, supplier_url=f'https://fr.aliexpress.com/item/{pid}.html'))
json.dump(out, open(os.path.join(os.path.dirname(__file__), 'products.json'), 'w'), ensure_ascii=False, indent=1)
print(len(out), 'produits')
